def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0] * w for _ in range(h)]
    colors = {v for row in grid for v in row} - {0}
    anchor = min(r for r, row in enumerate(grid) if 8 in row)
    for color in colors:
        cells = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == color]
        top = min(r for r, c in cells)
        for r, c in cells:
            out[r - top + anchor][c] = color
    return out
